// 1. Recupera os resultados e filtra "fantasmas" (objetos vazios sem ID)
const clientesEncontrados = items
  .map(item => item.json)
  .filter(item => item.id_cliente); // Só aceita se tiver ID

const qtd = clientesEncontrados.length;

// === CENÁRIO 1: NENHUM CLIENTE ENCONTRADO ===
if (qtd === 0) {
  return [{
    json: {
      encontrado: false,
      unico_match: false,
      mensagem_para_gpt: "Não consegui localizar nenhum cliente com esses dados. Por favor, verifique se o nome, CNPJ ou código estão corretos e tente novamente.",
      dados_cliente: null
    }
  }];
}

// === CENÁRIO 2: VÁRIOS CLIENTES (LISTA PARA ESCOLHA) ===
if (qtd > 1) {
  let listaTexto = `Encontrei ${qtd} clientes parecidos. Qual deles é o correto?\n`;

  for (const cli of clientesEncontrados) {
    // Tratamento de nulos para não aparecer "undefined"
    const nome = cli.razao_social || "Sem Nome";
    const fantasia = cli.fantasia ? `(${cli.fantasia})` : '';
    const cidade = cli.cidade || "N/D";
    const uf = cli.uf || "";
    const doc = cli.cnpj ? `| CNPJ: ${cli.cnpj}` : '';

    listaTexto += `\n🆔 **ID ${cli.id_cliente}** - ${nome} ${fantasia}\n   📍 ${cidade}/${uf} ${doc}\n`;
  }

  return [{
    json: {
      encontrado: true,
      unico_match: false, 
      mensagem_para_gpt: listaTexto,
      candidatos: clientesEncontrados 
    }
  }];
}

// === CENÁRIO 3: EXATAMENTE 1 CLIENTE ===
const unico = clientesEncontrados[0];
const nomeFinal = unico.fantasia || unico.razao_social || "Cliente";

return [{
  json: {
    encontrado: true,
    unico_match: true,
    mensagem_para_gpt: `Encontrei o cliente: ${nomeFinal} (ID ${unico.id_cliente}). Posso gerar o relatório?`,
    id_cliente_final: unico.id_cliente, 
    dados_completos: unico
  }
}];
